                                'n',
                            ),
                        ],
                        is_recursive: false,
                    },
                ],
                webviews: [],
                scope_id: Some(
                    1,
                ),
            },
        ],
    },
    denied_commands: {},
    command_scope: {
        1: ResolvedScope {
            allow: [
                Map(
                    {
                        "command": String(
                            "safari",
                        ),
                    },
                ),
            ],
            deny: [],
        },
    },
    global_scope: {
        "os": ResolvedScope {
            allow: [
                Map(
                    {
                        "path": String(
                            "$HOME/Library/**",
                        ),
                    },
                ),
            ],
            deny: [],
        },
    },
}

